import type { AudioTrackInfo, CaptionTrack, TextTrackInfo } from "../../core/types.js";

type AudioTrackLike = {
  readonly id?: string;
  readonly label?: string;
  readonly language?: string;
  enabled: boolean;
};

type MediaWithAudioTracks = HTMLMediaElement & {
  readonly audioTracks?: {
    readonly length: number;
    readonly [index: number]: AudioTrackLike | undefined;
  };
};

type MediaWithTextTracks = HTMLMediaElement & {
  readonly textTracks?: TextTrackList;
};

function textTrackId(track: TextTrack, index: number): string {
  return track.id.length > 0 ? track.id : `text-${index}`;
}

/** Reads the text tracks exposed by a media element. */
export function listTextTracks(media: MediaWithTextTracks): readonly TextTrackInfo[] {
  const tracks: TextTrackInfo[] = [];
  const textTracks = media.textTracks;

  if (textTracks === undefined) {
    return tracks;
  }

  for (let index = 0; index < textTracks.length; index += 1) {
    const track = textTracks[index];

    if (track === undefined) {
      continue;
    }

    tracks.push({
      id: textTrackId(track, index),
      label: track.label.length > 0 ? track.label : `Track ${index + 1}`,
      language: track.language,
      kind: track.kind as TextTrackInfo["kind"],
      default: track.mode === "showing",
    });
  }

  return tracks;
}

/** Shows one text track and disables the rest. */
export function setMediaTextTrack(media: MediaWithTextTracks, id: string | null): void {
  const textTracks = media.textTracks;

  if (textTracks === undefined) {
    return;
  }

  for (let index = 0; index < textTracks.length; index += 1) {
    const track = textTracks[index];

    if (track === undefined) {
      continue;
    }

    track.mode = id !== null && textTrackId(track, index) === id ? "showing" : "disabled";
  }
}

/** Reads the audio tracks exposed by a media element. */
export function listAudioTracks(media: MediaWithAudioTracks): readonly AudioTrackInfo[] {
  const tracks: AudioTrackInfo[] = [];
  const audioTracks = media.audioTracks;

  if (audioTracks === undefined) {
    return tracks;
  }

  for (let index = 0; index < audioTracks.length; index += 1) {
    const track = audioTracks[index];

    if (track === undefined) {
      continue;
    }

    tracks.push({
      id: track.id ?? `audio-${index}`,
      label: track.label ?? `Track ${index + 1}`,
      language: track.language ?? "",
      default: track.enabled,
    });
  }

  return tracks;
}

/** Enables one audio track and disables the rest. */
export function setMediaAudioTrack(media: MediaWithAudioTracks, id: string | null): void {
  const audioTracks = media.audioTracks;

  if (audioTracks === undefined) {
    return;
  }

  for (let index = 0; index < audioTracks.length; index += 1) {
    const track = audioTracks[index];

    if (track !== undefined) {
      track.enabled = track.id === id;
    }
  }
}

/**
 * Appends `<track>` elements for consumer-provided captions/subtitles.
 *
 * Native `<track>` only supports WebVTT. Callers should pass VTT URLs.
 */
export function applyCaptionTracks(
  media: HTMLMediaElement,
  tracks: readonly CaptionTrack[] | undefined,
): void {
  if (tracks === undefined || tracks.length === 0) {
    return;
  }

  for (let index = 0; index < tracks.length; index += 1) {
    const caption = tracks[index];

    if (caption === undefined) {
      continue;
    }

    const element = document.createElement("track");
    element.kind = caption.kind ?? "subtitles";
    element.label = caption.label;
    element.srclang = caption.language;
    element.src = caption.src;
    element.default = caption.default === true;

    if (caption.id !== undefined && caption.id.length > 0) {
      element.id = caption.id;
    }

    media.append(element);
  }
}

/** Applies the preferred caption id (or disables captions) after metadata. */
export function applyCaptionPreference(media: MediaWithTextTracks, id: string | null): void {
  if (id === null) {
    const textTracks = media.textTracks;

    if (textTracks === undefined) {
      return;
    }

    for (let index = 0; index < textTracks.length; index += 1) {
      const track = textTracks[index];

      if (track !== undefined) {
        track.mode = "disabled";
      }
    }

    return;
  }

  setMediaTextTrack(media, id);
}
